OR로 바꿀게요. 커밋과 배포도 확인 없이 진행하겠습니다.

dart
List<Note> filterNotes(List<Note> notes, String query, Set<String> tags) {
  return notes.where((n) {
    final matchesText = query.isEmpty ||
        n.title.contains(query) ||
        n.body.contains(query);
    final matchesTag = tags.isEmpty || n.tags.any(tags.contains);
    return matchesText && matchesTag;
  }).toList();
}
